package dev.koikaster.mite;
import java.util.*;import java.io.*;import java.nio.charset.StandardCharsets;import com.google.gson.*;import net.minecraft.world.item.*;import net.minecraft.world.item.crafting.*;import net.minecraftforge.registries.ForgeRegistries;
/** Explicit source recipe references; modern and original-less adapters add no skill. */
public final class SourceSkillRecipeLineage1857 {
 private record Rule(String output,int[] sets,String origin){}private static final Map<String,Rule> STATIC=new HashMap<>(),DYNAMIC=new HashMap<>();
 private static int[] sets(JsonElement e){if(e==null||e.isJsonNull())return null;int[] a=new int[e.getAsJsonArray().size()];for(int i=0;i<a.length;i++)a[i]=e.getAsJsonArray().get(i).getAsInt();return a;}
 private static JsonObject resource(String name)throws IOException{try(var in=SourceSkillRecipeLineage1857.class.getResourceAsStream("/data/mite_reforged/"+name)){if(in==null)throw new IOException("Missing source recipe lineage");return JsonParser.parseReader(new InputStreamReader(in,StandardCharsets.UTF_8)).getAsJsonObject();}}
 private static Rule rule(JsonObject row,Map<Integer,int[]> source){var ref=row.get("source_recipe");Integer index=ref==null||ref.isJsonNull()?null:ref.getAsInt();if(index!=null&&!source.containsKey(index))throw new IllegalStateException("Missing source recipe reference "+index);return new Rule(row.has("output")?row.get("output").getAsString():null,index==null?null:source.get(index),row.get("reason").getAsString()+(index==null?"":"_"+index));}
 static {try{var source=new HashMap<Integer,int[]>();for(var x:resource("source_skill_facts1709.json").getAsJsonArray("recipes")){var row=x.getAsJsonObject();source.put(row.get("index").getAsInt(),sets(row.get("skillsets")));}var data=resource("source_skill_recipe_lineage1857.json");for(var e:data.getAsJsonObject("recipes").entrySet())STATIC.put(e.getKey(),rule(e.getValue().getAsJsonObject(),source));for(var e:data.getAsJsonObject("dynamic").entrySet())DYNAMIC.put(e.getKey(),rule(e.getValue().getAsJsonObject(),source));}catch(IOException e){throw new ExceptionInInitializerError(e);}}
 public static SourceSkillFacts1710.Decision crafting(Recipe<?> recipe,ItemStack output){Rule rule;if(recipe instanceof MapExtendingRecipe)rule=DYNAMIC.get("map_extending");else if(recipe instanceof SourceBowlTransferRecipe)rule=DYNAMIC.get("bowl_transfer");else if(recipe instanceof VesselStoneRecipe)rule=DYNAMIC.get("stone_bucket");else if(recipe instanceof DisenchantingBottle.Recipe)rule=DYNAMIC.get("disenchanting_bottle");else if(recipe instanceof RustedIronContent.Reclaim)rule=DYNAMIC.get("rusted_reclaim");else if(recipe instanceof BannerDuplicateRecipe||recipe instanceof TippedArrowRecipe||recipe instanceof SuspiciousStewRecipe||recipe instanceof DecoratedPotRecipe||recipe instanceof ShulkerBoxColoring)rule=DYNAMIC.get("modern_dynamic");else rule=STATIC.get(recipe.getId().toString());if(rule==null)return null;var key=ForgeRegistries.ITEMS.getKey(output.getItem());if(rule.output!=null&&(key==null||!rule.output.equals(key.toString())))return null;return new SourceSkillFacts1710.Decision(true,rule.origin,rule.sets);}
 private SourceSkillRecipeLineage1857(){}
}
